 function setTrendHorizontal(s,enabled){if(s?.type!=='trend')return;s.straight=!!enabled;if(s.straight&&s.points?.length>=2){const price=(s.points[0].price+s.points[1].price)/2;s.points[0].price=price;s.points[1].price=price;}}
