 function chartSettings(){const before={theme:Theme.current,timezone:chartTimezone};let dialog;const prefs=JSON.parse(localStorage.getItem('btt2_chart_appearance')||'{}');const originalPrefs=clone(prefs);function apply(){Theme.apply(prefs.theme||Theme.current);app.chart?.applyOptions({grid:{vertLines:{visible:prefs.grid!==false},horzLines:{visible:prefs.grid!==false}},rightPriceScale:{mode:prefs.scale==='log'?1:0}});if(prefs.zone)setChartTimezone(prefs.zone);localStorage.setItem('btt2_chart_appearance',JSON.stringify(prefs));Renderer.render();sync();}
  dialog=createDialog('Chart settings',['Appearance','Chart','Workspace'],(box,tab)=>{if(tab==='Appearance')box.innerHTML=field('Theme','theme',prefs.theme||Theme.current,'select',{values:[['dark','Dark'],['light','Light']]})+field('Show grid','grid',prefs.grid!==false,'check')+'<small>Price scale: drag vertically to stretch or compress prices. Double-click the scale to restore automatic fitting.</small>';else if(tab==='Chart')box.innerHTML=field('Price scale','scale',prefs.scale||'normal','select',{values:[['normal','Regular'],['log','Logarithmic']]})+field('Display timezone','zone',chartTimezone,'select',{values:[['Africa/Lagos','UTC+1 Lagos'],['UTC','UTC'],['America/New_York','New York'],['Europe/London','London']]})+'<small>Changing display timezone changes labels only. Local CSV timestamps and drawing anchors stay attached to their candles.</small>';else box.innerHTML='<p>Your chart data stays on this PC. Export a workspace backup to keep a portable copy of drawings, templates, observations and settings.</p><button class="template-chip" id="settingsExport">Export backup</button><button class="template-chip" id="settingsImport">Import backup…</button>';box.querySelectorAll('[data-path]').forEach(input=>input.onchange=()=>{prefs[input.dataset.path]=input.type==='checkbox'?input.checked:input.value;apply();});if($('settingsExport'))$('settingsExport').onclick=exportWorkspace;if($('settingsImport'))$('settingsImport').onclick=importWorkspace;},{cancel:()=>closeProperties(false),buttons:[{spacer:true},{label:'Cancel',run:()=>closeProperties(false)},{label:'OK',primary:true,run:()=>{apply();closeProperties(true);}}]});properties={...dialog,drawing:false,cancel:()=>{Object.keys(prefs).forEach(k=>delete prefs[k]);Object.assign(prefs,originalPrefs);prefs.theme=before.theme;prefs.zone=before.timezone;apply();}};}
 function exportWorkspace(){const storage={};for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(key.startsWith('btt2'))storage[key]=localStorage.getItem(key);}const blob=new Blob([JSON.stringify({format:'BTT2-workspace',version:1,created:new Date().toISOString(),storage},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='BTT-2-workspace-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Workspace backup exported');}
 function importWorkspace(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file||file.size>15*1024*1024)throw Error('Choose a workspace JSON smaller than 15 MB.');const p=JSON.parse(await file.text());if(p.format!=='BTT2-workspace'||p.version!==1||!p.storage||typeof p.storage!=='object')throw Error('This is not a BTT 2 workspace backup.');const entries=Object.entries(p.storage);if(entries.some(([k,v])=>!k.startsWith('btt2')||typeof v!=='string'))throw Error('Invalid storage values in backup.');const backup={};for(const[k]of entries)backup[k]=localStorage.getItem(k);try{for(const[k,v]of entries)localStorage.setItem(k,v);}catch(e){for(const[k,v]of Object.entries(backup))v==null?localStorage.removeItem(k):localStorage.setItem(k,v);throw e;}toast('Backup imported. Reloading workspace…');setTimeout(()=>location.reload(),500);}catch(e){toast(e.message);}};input.click();}
 function help(){let dialog;dialog=createDialog('Make the chart yours',['Shortcuts'],box=>{box.innerHTML='<div class="dialog-summary">Esc · Cancel drawing or close a menu<br>Ctrl Z · Undo drawing change<br>Ctrl Shift Z / Ctrl Y · Redo<br>Delete · Remove selected drawing<br>Ctrl D · Duplicate selected drawing<br>Alt T · Trendline<br>Alt H · Horizontal line<br>Alt J · Horizontal ray<br>Alt V · Vertical line<br>Alt R · Reset chart view<br>Shift while drawing · Constrain trendline angle<br>Right-click · Contextual drawing or chart actions<br>Double-click drawing · Detailed properties<br>Drag price scale · Stretch or compress prices<br>Double-click price scale · Auto fit</div><small>Cross and Dot cursor modes are available from the top of the drawing rail. Right-click Magnet to choose weak or strong snapping. The chart uses your local CSV history.</small>';},{cancel:()=>closeProperties(false),buttons:[{spacer:true},{label:'Done',primary:true,run:()=>closeProperties(true)}]});properties={...dialog,drawing:false};}
