 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&activeMenu){dismissMenu();e.preventDefault();e.stopImmediatePropagation();return;}if(activeMenu&&['ArrowDown','ArrowUp'].includes(e.key)){const list=[...activeMenu.querySelectorAll('button:not(:disabled)')],index=list.indexOf(document.activeElement);list[(index+(e.key==='ArrowDown'?1:-1)+list.length)%list.length]?.focus();e.preventDefault();}if(e.key==='Escape'&&properties){closeProperties(false);e.preventDefault();e.stopImmediatePropagation();return;}if(properties||e.target.closest('input,textarea,select,[contenteditable=true]'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='d'){e.preventDefault();duplicate(Store.selected());}if(e.altKey){const tool={t:'trend',h:'hline',j:'hray',v:'vline'}[e.key.toLowerCase()];if(tool){e.preventDefault();D.setTool(tool);}if(e.key.toLowerCase()==='r'){e.preventDefault();resetView();}}},true);
