 const originalWlItem=makeWlItem;makeWlItem=function(symbol,section){const row=originalWlItem(symbol,section);const more=document.createElement('button');more.type='button';more.className='wl-touch-menu';more.textContent='⋯';more.setAttribute('aria-label','Actions for '+symbol);more.onclick=e=>{e.stopPropagation();const r=more.getBoundingClientRect();showWlMenu(r.left,r.bottom,symbol,section||'pairs');};row.append(more);return row;};
 let narrowDock=innerWidth<=900;window.addEventListener('resize',()=>{const next=innerWidth<=900;if(next===narrowDock)return;const dock=$('rightDock');if(!dock)return;const open=narrowDock?dock.classList.contains('mobile-open'):!dock.classList.contains('closed');narrowDock=next;dock.classList.remove('mobile-open');setDock(dockMode,open);});
